'use strict';

// MODULES //

var factory = require( '@stdlib/ndarray/tensor0d/ctor' ).factory;


// VARIABLES //

var ctor = factory( 'generic' );


// MAIN //

/**
* Returns a "generic" zero-dimensional ndarray.
*
* @param {*} value - scalar value
* @param {Options} [options] - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray
* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
* @throws {Error} must provide a scalar value
* @throws {TypeError} must provide valid options
* @returns {ndarray} zero-dimensional ndarray
*
* @example
* var arr = new GenericTensor0D( 1.0 );
* // returns <ndarray>[ 1.0 ]
*/
function GenericTensor0D( value ) {
	var nargs = arguments.length;
	if ( nargs < 1 ) {
		throw new Error( 'invalid invocation. Insufficient arguments. Must provide a scalar value.' );
	}
	if ( nargs === 1 ) {
		return new ctor( value );
	}
	return new ctor( value, arguments[ 1 ] );
}


// EXPORTS //

module.exports = GenericTensor0D;
